grid = [list(map(int, line.split())) for line in grid_str.strip().split('\n')]
height, width = len(grid), len(grid[0])

def find_components_grid_color(color):
    visited = set()
    components = []
    coords = []
    for r in range(height):
        for c in range(width):
            if 0 <= r < height and 0 <= c < width:
                cell = grid[r][c]
                if cell == color:
                    coords.append((r, c))

    for (r, c) in coords:
        if (r, c) not in visited:
            component = []
            queue = [(r, c)]
            visited.add((r, c))
            while queue:
                cr, cc = queue.pop(0)
                component.append((cr, cc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == color and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
            components.append(component)
    return components

def canonical_shape(cells):
    if not cells:
        return ()
    min_r = min(c[0] for c in cells)
    min_c = min(c[1] for c in cells)
    norm_cells = sorted((r - min_r, c - min_c) for r, c in cells)
    return tuple(norm_cells)

# Build mapping: shape -> color (for all non-1 colors)
shape_to_color = {}

for color in sorted([c for c in range(1, 10) if c != 1]):
    comps = find_components_grid_color(color)
    for comp in comps:
        shape_key = canonical_shape(comp)
        if shape_key not in shape_to_color:
            shape_to_color[shape_key] = color

